using System.Drawing.Design;
using System.Windows.Forms;
using System.Windows.Forms.Design;

public class MyControl : UserControl
{
    public string DisplayName { get; set; }
    public int MaxItems { get; set; }

    protected override void OnLoad(EventArgs e)
    {
        base.OnLoad(e);

        // .NET 9 breaking change: StatusStrip no longer inherits ToolStripManager.RenderMode.
        // Explicitly set the renderer to preserve the previous visual behavior.
        ToolStripManager.RenderMode = ToolStripRenderMode.System;
    }

    /// <summary>
    /// Demonstrates guarding against null when calling DropDownControl.
    /// .NET 9 breaking change: IWindowsFormsEditorService.DropDownControl now throws
    /// ArgumentNullException if control is null.
    /// </summary>
    public static void ShowDropDown(IWindowsFormsEditorService editorService, Control? control)
    {
        if (control is null)
            return;

        editorService.DropDownControl(control);
    }
}

